      questions: [
        {q: "A first order reaction has a rate constant of 0.0693 min^-1. Calculate its half-life.", a: "For first order reaction, t1/2 = 0.693/k = 0.693/0.0693 = 10 min. Final answer: Half-life = 10 minutes."},
        {q: "A first order reaction is 50% complete in 20 minutes. Calculate the time required for 87.5% completion.", a: "t1/2 = 20 min so k = 0.693/20 = 0.03465 min^-1. For 87.5% completion, remaining = 12.5% = 1/8, i.e., 3 half-lives. Time = 3*20 = 60 min. Final answer: Time required for 87.5% completion = 60 minutes."}
      ]
